#!/usr/bin/env python3
"""Bundle policy fixture tests, not a native macOS compilation/launch claim."""
import importlib.util
from contextlib import contextmanager
import hashlib
import json
from pathlib import Path
import plistlib
import shutil
import subprocess
import zipfile
import tempfile
import sys
from unittest.mock import patch

# Importing the packaging helper must not dirty the source checkout with generated bytecode.
sys.dont_write_bytecode = True
script = Path(__file__).resolve().parent / 'package-macos.py'
spec = importlib.util.spec_from_file_location('package_macos', script)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

with tempfile.TemporaryDirectory(prefix='pipkin-mac-bundle-test-') as temporary:
    root = Path(temporary)
    files = {'Cargo.toml': '[workspace.package]\nversion = "0.0.1"\n',
             'target/release/pipkin': 'fixture binary', 'LICENSE': 'MIT fixture',
             'SECURITY.md': 'security fixture', 'assets/PROVENANCE.md': 'asset fixture',
             'packaging/upstream-notices/anthropic-sdk/LICENSE': 'Anthropic SDK MIT fixture',
             'packaging/pipkin.icns': 'fixture app icon',
             'packaging/dmg-background.tiff': 'fixture instructional background',
             'packaging/dmg-layout.json': json.dumps({'canvas': [800, 520], 'windowOrigin': [100, 100],
                 'iconSize': 128, 'textSize': 14, 'icons': {'Pipkin.app': [260, 322], 'Applications': [580, 322]},
                 'background': '.background/install.tiff'}),
             'assets/fonts/example-OFL.txt': 'font fixture',
             'docs/macos-first-pass.md': 'experimental instructions',
             'packaging/pi-engine-revision': 'a' * 40,
             'dist/macos-notices/usr/lib/pipkin/engine/engine.json': json.dumps({'sourceRevision': 'a' * 40, 'development': False, 'productionPruneSucceeded': True}),
             'dist/macos-notices/usr/lib/pipkin/engine/pi-test.sh': 'fixture launcher',
             'dist/macos-notices/usr/lib/pipkin/runtime/bin/node': 'fixture node',
             'dist/macos-notices/usr/lib/pipkin/runtime/LICENSE': 'full Node notice',
             'dist/macos-notices/usr/lib/pipkin/runtime/runtime.json': json.dumps({'target': 'aarch64-apple-darwin', 'version': '22.23.3', 'binarySha256': hashlib.sha256(b'fixture node').hexdigest()}),
             'dist/macos-notices/usr/share/doc/pipkin/third-party/inventory.json': '{}',
             'dist/macos-notices/usr/share/doc/pipkin/third-party/sources/mpl/src/lib.rs': 'exact source'}
    for relative, text in files.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
    (root / 'target/release/pipkin').chmod(0o755)

    def output(args, **kwargs):
        if args[:2] == ['git', 'rev-parse']:
            return 'b' * 40 + '\n'
        if args[:2] == ['git', 'status']:
            return b''
        if args == ['/usr/sbin/bless', '--help']:
            return 'fixture: unsupported open-folder metadata option'
        if args[0] == 'otool':
            return '/private/fixture/executable:\n\t/usr/lib/libSystem.B.dylib (compatibility version 1.0.0)\n'
        if args[:3] == ['xcrun', 'GetFileInfo', '-a']:
            assert kwargs['text'] is True
            assert (Path(args[3]) / '.VolumeIcon.icns').exists()
            return 'C\n' if image_state['has_custom_icon'] and not hide_volume_flag else '-\n'
        raise AssertionError(args)

    calls = []
    probe_profiles = []
    corrupt_extraction = False
    corrupt_dmg = False
    fail_attach = False
    dmg_payload = None
    image_state = {'writable': None, 'has_custom_icon': False}
    corrupt_volume_icon = False
    hide_volume_flag = False
    fail_setfile = False
    corrupt_background = False
    missing_background = False
    fail_layout_write = False
    missing_metadata = False
    corrupt_metadata = False
    tools_calls = []

    @contextmanager
    def tools_fixture(manifest):
        tools_calls.append(manifest)
        with tempfile.TemporaryDirectory() as tools:
            yield Path(tools)

    def layout_fixture(tools, action, mount, layout, source):
        # Integration fixture only. Real binary DS_Store/alias semantics are tested
        # separately by test-macos-dmg-layout.py against the pinned wheels.
        assert Path(tools).is_dir()
        mount = Path(mount)
        if action == 'write':
            if fail_layout_write:
                raise RuntimeError('fixture layout write failure')
            (mount / '.background').mkdir(exist_ok=True)
            shutil.copy2(source, mount / '.background/install.tiff')
            (mount / '.DS_Store').write_text(Path(layout).read_text())
        elif action == 'verify':
            if not (mount / '.DS_Store').is_file() or (mount / '.DS_Store').read_text() != Path(layout).read_text():
                raise RuntimeError('mounted DMG Finder metadata missing or invalid')
            if not (mount / '.background/install.tiff').is_file() or module.sha256(mount / '.background/install.tiff') != module.sha256(source):
                raise RuntimeError('mounted DMG background checksum mismatch')
        else:
            raise AssertionError(action)

    def seal(contents):
        return {str(p.relative_to(contents)): module.sha256(p) for p in contents.rglob('*')
                if p.is_file() and '_CodeSignature' not in p.parts}

    def command(args, **kwargs):
        global dmg_payload
        if args[:2] == ['hdiutil', 'detach'] and 'stdout' in kwargs:
            assert kwargs['check'] is False  # Cleanup after a partially successful attach.
        else:
            assert kwargs['check'] is True
        calls.append(args)
        if args[:2] == ['codesign', '--force']:
            assert args[2:6] == ['--sign', '-', '--identifier', 'org.last-refuge.pipkin']
            contents = Path(args[-1]) / 'Contents'
            executable = contents / 'MacOS/pipkin'
            executable.write_bytes(executable.read_bytes() + b' fixture signature')
            signature = contents / '_CodeSignature/CodeResources'
            signature.parent.mkdir()
            signature.write_text(json.dumps(seal(contents)))
        elif args[:2] == ['codesign', '--verify']:
            assert args[2:5] == ['--deep', '--strict', '--verbose=4']
            contents = Path(args[-1]) / 'Contents'
            if json.loads((contents / '_CodeSignature/CodeResources').read_text()) != seal(contents):
                raise subprocess.CalledProcessError(1, args)
        elif args[:5] == ['ditto', '-c', '-k', '--sequesterRsrc', '--keepParent']:
            bundle = Path(args[-2]); contents = bundle / 'Contents'
            assert (contents / 'MacOS/pipkin').stat().st_mode & 0o111
            plist = plistlib.loads((contents / 'Info.plist').read_bytes())
            assert plist['CFBundleExecutable'] == 'pipkin'
            assert plist['CFBundleIconFile'] == 'pipkin.icns'
            assert (contents / 'Resources/pipkin.icns').read_text() == 'fixture app icon'
            assert (contents / 'Resources/third-party/sources/mpl/src/lib.rs').read_text() == 'exact source'
            assert (contents / 'Resources/font-notices/example-OFL.txt').exists()
            assert (contents / 'Resources/anthropic-sdk-MIT-LICENSE').read_text() == 'Anthropic SDK MIT fixture'
            embedded = json.loads((contents / 'Resources/build-info.json').read_text())
            assert 'binarySha256' not in embedded['app']  # No self-referential signature hash.
            assert embedded['app']['preBundleSigningBinarySha256'] == module.sha256(root / 'target/release/pipkin')
            with zipfile.ZipFile(args[-1], 'w') as archive:
                for path in bundle.rglob('*'):
                    if path.is_file():
                        archive.write(path, path.relative_to(bundle.parent))
        elif args[:3] == ['ditto', '-x', '-k']:
            with zipfile.ZipFile(args[3]) as archive:
                archive.extractall(args[4])
            if corrupt_extraction:
                (Path(args[4]) / 'Pipkin.app/Contents/Resources/README.md').write_text('tampered resource')
        elif args[:2] == ['hdiutil', 'create']:
            assert args[2:5] == ['-volname', 'Pipkin', '-srcfolder']
            assert args[6:11] == ['-format', 'UDRW', '-fs', 'HFS+', '-ov']
            payload = Path(args[5])
            assert sorted(p.name for p in payload.iterdir()) == ['.background', 'Applications', 'Pipkin.app']
            assert module.sha256(payload / '.background/install.tiff') == module.sha256(root / 'packaging/dmg-background.tiff')
            assert (payload / 'Applications').is_symlink()
            assert (payload / 'Applications').readlink() == Path('/Applications')
            dmg_payload = payload
            image_state['has_custom_icon'] = False
            Path(args[-1]).write_bytes(b'fixture writable disk image')
        elif args[:2] == ['hdiutil', 'convert']:
            assert Path(args[2]).read_bytes() == b'fixture writable disk image'
            assert args[3:6] == ['-format', 'UDZO', '-o']
            assert image_state['has_custom_icon']
            assert calls[-2][:2] == ['hdiutil', 'detach']
            Path(args[-1]).write_bytes(b'fixture compressed disk image')
        elif args[:2] == ['hdiutil', 'attach']:
            writable = args[2] == '-readwrite'
            assert args[2:6] == ['-readwrite' if writable else '-readonly', '-nobrowse', '-mountpoint', args[5]]
            assert Path(args[-1]).read_bytes() == (b'fixture writable disk image' if writable else b'fixture compressed disk image')
            mount = Path(args[5])
            shutil.copytree(dmg_payload / 'Pipkin.app', mount / 'Pipkin.app', symlinks=True)
            (mount / 'Applications').symlink_to('/Applications', target_is_directory=True)
            if writable:
                shutil.copytree(dmg_payload / '.background', mount / '.background')
                image_state['writable'] = mount
            else:
                shutil.copy2(image_state['writable'] / '.VolumeIcon.icns', mount / '.VolumeIcon.icns')
                shutil.copytree(image_state['writable'] / '.background', mount / '.background')
                shutil.copy2(image_state['writable'] / '.DS_Store', mount / '.DS_Store')
                if corrupt_background:
                    (mount / '.background/install.tiff').write_text('tampered background')
                if missing_background:
                    (mount / '.background/install.tiff').unlink()
                if missing_metadata:
                    (mount / '.DS_Store').unlink()
                if corrupt_metadata:
                    (mount / '.DS_Store').write_text('tampered settings')
                if corrupt_volume_icon:
                    (mount / '.VolumeIcon.icns').write_text('tampered volume icon')
            if corrupt_dmg and not writable:
                (mount / 'Pipkin.app/Contents/Resources/README.md').write_text('tampered image')
            if fail_attach:
                raise subprocess.CalledProcessError(1, args)
        elif args[:2] == ['xcrun', 'SetFile']:
            assert args[2:4] == ['-a', 'C']
            assert Path(args[4]) == image_state['writable']
            assert (image_state['writable'] / '.VolumeIcon.icns').read_text() == 'fixture app icon'
            if fail_setfile:
                raise subprocess.CalledProcessError(1, args)
            image_state['has_custom_icon'] = True
        elif args[:2] == ['hdiutil', 'detach']:
            assert Path(args[2]).is_dir()
        elif '--diagnose' in args:
            assert '--probe' in args
            assert kwargs['env']['PATH'] == '/usr/bin:/bin:/usr/sbin:/sbin'
            assert set(kwargs['env']) == {'PATH', 'HOME', 'TMPDIR', 'PI_OFFLINE'}
            profile = Path(kwargs['env']['TMPDIR'])
            assert profile == Path(kwargs['env']['HOME'])
            assert profile.parent == Path('/tmp') and len(profile.name) == 8
            assert profile.stat().st_mode & 0o077 == 0  # Disposable private profile.
            module.check_probe_socket_budget(profile)
            probe_profiles.append(profile)
            contents = Path(args[0]).parent.parent
            assert json.loads((contents / 'lib/pipkin/engine/engine.json').read_text())['requiresBundledNode']
            assert (contents / 'lib/pipkin/runtime/LICENSE').read_text() == 'full Node notice'
        else:
            raise AssertionError(args)

    with patch.object(module, 'ROOT', root), patch.object(module.sys, 'platform', 'darwin'), patch.object(module.sys, 'argv', [str(script), 'aarch64-apple-darwin']), patch.object(module.subprocess, 'check_output', side_effect=output), patch.object(module.subprocess, 'run', side_effect=command), patch.object(module.dmg_layout, 'private_tools', side_effect=tools_fixture), patch.object(module.dmg_layout, 'run_layout', side_effect=layout_fixture):
        module.main()
        out = root / 'dist/macos'
        info = json.loads((out / 'build-info.json').read_text())
        assert info['experimental'] and info['engine']['bundled']
        assert info['nodeRuntime']['version'] == '22.23.3'
        assert info['app']['target'] == 'aarch64-apple-darwin'
        assert info['app']['revision'] == 'b' * 40 and info['app']['dirty'] is False
        assert info['app']['preBundleSigningBinarySha256'] == module.sha256(root / 'target/release/pipkin')
        assert info['app']['binarySha256'] != info['app']['preBundleSigningBinarySha256']
        assert sum(args[:2] == ['codesign', '--verify'] for args in calls) == 5
        assert 'Developer ID' in info['signing']
        assert temporary not in (out / 'build-info.json').read_text()
        assert '/private/fixture' not in (out / 'build-info.json').read_text()
        assert not (out / 'Pipkin.app').exists()
        package = next(out.glob('*.zip'))
        dmg = next(out.glob('*.dmg'))
        assert (out / 'SHA256SUMS').read_text() == (
            f'{module.sha256(package)}  {package.name}\n{module.sha256(dmg)}  {dmg.name}\n')
        assert sum('--probe' in args for args in calls) == 2  # Extracted ZIP and copied DMG app.
        assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == 2
        assert len(probe_profiles) == 2
        # Regression: the prior longer pk-dmg- prefix crossed Pi's private socket budget.
        try:
            module.check_probe_socket_budget('/tmp/pk-dmg-abcdefgh')
            raise AssertionError('oversized Pi socket path accepted')
        except RuntimeError as error:
            assert 'socket-path limit' in str(error)
        before = len(calls)
        tools_before = len(tools_calls)
        with patch.object(module.sys, 'argv', [str(script), 'aarch64-apple-darwin', '--app-only']), \
                patch.object(module.dmg_layout, 'read_layout', side_effect=AssertionError('app-only read DMG settings')):
            module.main()
        assert (out / 'Pipkin.app').exists()
        assert not list(out.glob('*.dmg'))
        assert len(tools_calls) == tools_before  # No DMG tools fetch/settings for app-only.
        assert not any(args[0] in ('hdiutil', 'xcrun', '/usr/sbin/bless') for args in calls[before:])
        assert sum('--probe' in args for args in calls[before:]) == 1
        assert sum(args[:2] == ['codesign', '--verify'] for args in calls[before:]) == 3
        module.main()  # An identified prior output can be replaced.
        for failure in ('corrupt_background', 'missing_background', 'missing_metadata', 'corrupt_metadata'):
            globals()[failure] = True
            before_detach = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
            try:
                module.main()
                raise AssertionError('tampered/missing DMG layout accepted')
            except RuntimeError as error:
                assert 'background' in str(error) or 'Finder metadata' in str(error)
                assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before_detach + 2
                assert not (out / 'SHA256SUMS').exists()
            finally:
                globals()[failure] = False
        fail_layout_write = True
        before_detach = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
        try:
            module.main()
            raise AssertionError('failed layout write accepted')
        except RuntimeError as error:
            assert 'layout write failure' in str(error)
            assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before_detach + 1
            assert not (out / 'SHA256SUMS').exists()
        fail_layout_write = False
        corrupt_dmg = True
        before = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
        try:
            module.main()
            raise AssertionError('tampered mounted app was accepted')
        except subprocess.CalledProcessError:
            assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before + 2
            assert not (out / 'SHA256SUMS').exists()
        corrupt_dmg = False
        fail_attach = True
        before = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
        try:
            module.main()
            raise AssertionError('failed attach was accepted')
        except subprocess.CalledProcessError:
            assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before + 1
            assert not (out / 'SHA256SUMS').exists()
        fail_attach = False
        corrupt_volume_icon = True
        before = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
        try:
            module.main()
            raise AssertionError('altered volume icon was accepted')
        except RuntimeError as error:
            assert 'volume icon' in str(error)
            assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before + 2
            assert not (out / 'SHA256SUMS').exists()
        corrupt_volume_icon = False
        hide_volume_flag = True
        before = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
        try:
            module.main()
            raise AssertionError('missing volume icon flag was accepted')
        except RuntimeError as error:
            assert 'custom volume icon flag' in str(error)
            assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before + 2
            assert not (out / 'SHA256SUMS').exists()
        hide_volume_flag = False
        fail_setfile = True
        before = sum(args[:2] == ['hdiutil', 'detach'] for args in calls)
        try:
            module.main()
            raise AssertionError('failed custom icon operation was accepted')
        except subprocess.CalledProcessError:
            assert sum(args[:2] == ['hdiutil', 'detach'] for args in calls) == before + 1
            assert not (out / 'SHA256SUMS').exists()
        fail_setfile = False
        corrupt_extraction = True
        try:
            module.main()
            raise AssertionError('tampered extracted resources were accepted')
        except subprocess.CalledProcessError:
            assert not (out / 'SHA256SUMS').exists()  # Do not publish a failed bundle.
    with patch.object(module.sys, 'platform', 'linux'):
        try:
            module.main()
            raise AssertionError('non-macOS packaging was accepted')
        except SystemExit as error:
            assert 'native build on macOS' in str(error)
print('macOS bundle/notice/source/identity/checksum policy fixtures passed; no native build claimed')
